import{_ as t,o as d,c as a,ae as o}from"./chunks/framework.Czhw_PXq.js";const u=JSON.parse('{"title":"后端与模型","description":"","frontmatter":{},"headers":[],"relativePath":"reference/backend.md","filePath":"reference/backend.md"}'),l={name:"reference/backend.md"};function r(i,e,c,p,s,n){return d(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="后端与模型" tabindex="-1">后端与模型 <a class="header-anchor" href="#后端与模型" aria-label="Permalink to &quot;后端与模型&quot;">​</a></h1><p>本页说明后端模块的职责、数据流和存储约定，帮助你快速定位实现代码。</p><h2 id="入口与生命周期" tabindex="-1">入口与生命周期 <a class="header-anchor" href="#入口与生命周期" aria-label="Permalink to &quot;入口与生命周期&quot;">​</a></h2><ul><li><code>app/main.py</code>：应用入口，负责创建 <code>FastAPI</code> 实例、挂载静态资源、注册路由、启动定时任务以及请求日志中间件。</li><li>启动时会执行数据库初始化，并创建图库、云盘和分片上传需要的目录。</li><li><code>app.state.settings</code> 会保存运行配置，便于路由和中间件读取。</li></ul><h2 id="模块分工" tabindex="-1">模块分工 <a class="header-anchor" href="#模块分工" aria-label="Permalink to &quot;模块分工&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模块</th><th>职责</th></tr></thead><tbody><tr><td><code>app/api/routes/health.py</code></td><td>健康检查。</td></tr><tr><td><code>app/api/routes/gallery.py</code></td><td>图库上传、访问、登录、统计和后台管理。</td></tr><tr><td><code>app/api/routes/cloud.py</code></td><td>云盘文件管理、分享、公共访问、分片上传和统计。</td></tr><tr><td><code>app/api/routes/snippet.py</code></td><td>代码片管理、分享、公共访问与下载。</td></tr><tr><td><code>app/api/routes/frontend.py</code></td><td>静态前端入口路由。</td></tr><tr><td><code>app/core/security.py</code></td><td>管理端鉴权、JWT / 静态令牌解析。</td></tr><tr><td><code>app/core/corn.py</code></td><td>定时任务调度，负责同步图库预览与清理过期分享。</td></tr><tr><td><code>app/services/gallery.py</code></td><td>图库文件存储、预览生成、统计与访问控制。</td></tr><tr><td><code>app/services/cloud.py</code></td><td>云盘文件和目录操作。</td></tr><tr><td><code>app/services/cloud_share.py</code></td><td>分享创建、校验、过期处理与访问记录。</td></tr><tr><td><code>app/services/cloud_chunk_upload.py</code></td><td>分片上传任务管理与合并。</td></tr><tr><td><code>app/models/</code></td><td>SQLAlchemy ORM 模型。</td></tr><tr><td><code>app/schemas/</code></td><td>请求和响应结构。</td></tr><tr><td><code>app/core/config.py</code></td><td>环境变量与默认配置。</td></tr></tbody></table><h2 id="存储结构" tabindex="-1">存储结构 <a class="header-anchor" href="#存储结构" aria-label="Permalink to &quot;存储结构&quot;">​</a></h2><p>当前代码的存储路径约定如下：</p><ul><li><code>storage/gallery/original/</code>：图库原始文件。</li><li><code>storage/gallery/preview/</code>：图库预览图。</li><li><code>storage/cloud/</code>：云盘文件。</li><li><code>storage/cloud/.uploads/</code>：分片上传临时文件与任务元数据。</li><li><code>storage/snippets/</code>：代码片正文文件与本地混合存储内容。</li><li><code>storage/</code>：根存储目录，可通过 <code>STORAGE_PATH</code> 调整。</li></ul><p>图库服务还保留了旧路径兼容逻辑，会自动迁移或回读 <code>storage/original/</code> 和 <code>storage/preview/</code>，避免升级后旧数据失效。</p><h2 id="图库处理流程" tabindex="-1">图库处理流程 <a class="header-anchor" href="#图库处理流程" aria-label="Permalink to &quot;图库处理流程&quot;">​</a></h2><ol><li>上传文件后先计算大小、类型和 MIME。</li><li>图片会尝试生成 WebP 预览图，云盘上传则按异步补齐策略维护预览文件。</li><li>元数据写入数据库，包括短链、文件名、尺寸、访问模式和统计信息。</li><li>访问图片时会先校验权限，再按 <code>VIEW_ORIGIN</code> 决定返回原图还是预览。</li></ol><h2 id="云盘处理流程" tabindex="-1">云盘处理流程 <a class="header-anchor" href="#云盘处理流程" aria-label="Permalink to &quot;云盘处理流程&quot;">​</a></h2><ol><li>云盘文件存储在 <code>storage/cloud</code> 下。</li><li>文件管理支持上传、重命名、移动、复制、删除与批量操作，并提供目录层级导航和右键菜单。</li><li>分享功能会生成分享码，并支持密码、过期时间和短链 <code>/f/{share_code}</code>。</li><li>分片上传会先初始化任务，再逐片上传，最后合并并保存为正式文件。</li><li>定时任务会清理过期分享，并同步图库缺失的预览文件。</li></ol><h2 id="代码片处理流程" tabindex="-1">代码片处理流程 <a class="header-anchor" href="#代码片处理流程" aria-label="Permalink to &quot;代码片处理流程&quot;">​</a></h2><ol><li>代码片正文写入本地 <code>storage/snippets/</code>，数据库仅保存正文路径、大小和哈希等元信息。</li><li>列表与详情接口从本地正文文件读取内容，再进行高亮和预览渲染。</li><li>分享与下载接口直接读取本地正文文件，避免把大文本长期作为数据库主负载。</li><li>代码片分享会生成分享码，支持密码、过期时间、访问次数和一次性分享。</li></ol><h2 id="权限模型" tabindex="-1">权限模型 <a class="header-anchor" href="#权限模型" aria-label="Permalink to &quot;权限模型&quot;">​</a></h2><ul><li>图库管理端依赖管理员 JWT 登录态，必要时也可通过静态 <code>ADMIN_TOKEN</code> 访问。</li><li>公共图片访问可通过全局签名或单独签名控制。</li><li>云盘管理接口同样依赖管理员登录态。</li><li><code>ADMIN_TOKEN</code> 为空时，静态令牌通道会自动关闭。</li></ul><h2 id="统计项" tabindex="-1">统计项 <a class="header-anchor" href="#统计项" aria-label="Permalink to &quot;统计项&quot;">​</a></h2><p>图库和云盘都提供统计接口：</p><ul><li>图库统计：总图片数、总大小、总访问量、今日上传/访问、热门图片、来源和访问 IP 统计。</li><li>云盘统计：总文件数、文件夹数、总大小、总空间、可用空间、近期上传、热门访问条目和近期访问 TOP5。</li><li>代码片统计：代码片总数、公开代码片、有效分享、总代码行数、分享访问量、语言分布 Top5 和最近访问 Top5。</li></ul>',21)])])}const _=t(l,[["render",r]]);export{u as __pageData,_ as default};
